import json,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle,Circle
from pathlib import Path
s=json.loads(Path('hardware/kicad/qualification/issue-182-matrix-rev3/inspection/GLOBAL-02/snapshot.json').read_text())
fig,axs=plt.subplots(1,2,figsize=(16,9))
colors={'WING_EN':'lime','GND':'orange','HALL_5V':'red','MUX_A0':'cyan','MUX_A1':'violet','MUX_A2':'pink'}
for l,ax in zip([0,2],axs):
 ax.set_facecolor('#141b22')
 for t in s['tracks']:
  c=colors.get(t['net'],'#7b8997')
  if t['kind']=='track' and t['layer']==l:
   a,z=t['start'],t['end'];ax.plot([a[0],z[0]],[a[1],z[1]],color=c,linewidth=t['width']*25,solid_capstyle='round')
  if t['kind']=='via':
   x,y=t['position'];ax.add_patch(Circle((x,y),t['size']/2,facecolor=c,edgecolor='white'));ax.add_patch(Circle((x,y),t['drill']/2,facecolor='black'))
 for q in s['pads']:
  if l not in q['layers']:continue
  x,y=q['position'];w,h=q['size'];c=colors.get(q['net'],'#7b8997');ax.add_patch(Rectangle((x-w/2,y-h/2),w,h,facecolor=c,alpha=.8))
  if 75<x<88 and 116<y<125:ax.text(x,y,q['ref']+'.'+q['number'],fontsize=6)
 ax.set_xlim(75.5,88.5);ax.set_ylim(125,116);ax.set_aspect('equal');ax.set_title(str(l));ax.grid(alpha=.15)
fig.savefig('hardware/kicad/qualification/issue-182-matrix-rev3/inspection/mux-a-global2.png',dpi=130)
